// Optional "Draft with AI" panel. The client only displays server answers; the ceiling, validation, the risk text and
// the save acknowledgement are all enforced/generated by the API. Nothing here saves, runs or approves anything.
import { api, h, clear, labelled, badge, errorText, ApiError } from './lib.js';

export function reviewView(review) {
  const removed = review.diff_vs_ceiling.requested_but_removed;
  return h('section', { class: 'card assist-review', 'aria-labelledby': 'assist-review-h' },
    h('h3', { id: 'assist-review-h' }, 'Permissions review'),
    h('p', null, badge(review.label, 'bad'), ' ', badge('risk: ' + review.risk.level, 'risk-' + review.risk.level)),
    h('ul', { class: 'assist-reasons' }, review.risk.reasons.map((r) => h('li', null, badge(r.level, 'risk-' + r.level), ' ', r.reason))),
    h('h4', null, 'What it may do'),
    h('ul', null, review.permissions.capabilities.map((c) => h('li', null, h('strong', null, c.id), ': ', c.meaning,
      c.requires_approval ? ' Needs your approval each time.' : ''))),
    h('p', null, 'Network: ', typeof review.permissions.network === 'string' ? review.permissions.network
      : review.permissions.network.map((n) => n.meaning).join(' ')),
    h('p', null, 'Workspace: ', review.permissions.workspace, '. Agent: ', review.permissions.executor, '.'),
    h('ul', null, review.permissions.limits.map((l) => h('li', null, l.meaning))),
    h('h4', null, 'Requested but changed or removed'),
    removed.length ? h('ul', null, removed.map((c) => h('li', null, h('strong', null, c.action), ' ', c.field, ': ',
      c.requested === null ? '' : `asked for ${JSON.stringify(c.requested)}`, c.applied === null ? ', removed' : `, now ${JSON.stringify(c.applied)}`, ' — ', c.reason)))
      : h('p', { class: 'hint' }, 'Nothing was removed: the draft stayed within the ceiling.'),
    h('p', { class: 'hint' }, 'Risk text is generated by code from the validated specification, not by the model. Review id ', review.review_sha256.slice(0, 16), '.'));
}

// onDraft(draft) loads the draft into the editable form. Returns the panel element.
export function assistPanel(status, onDraft) {
  const box = h('section', { class: 'card assist', 'aria-labelledby': 'assist-h' }, h('h3', { id: 'assist-h' }, 'Draft with AI (optional)'));
  if (!status.available) {
    box.append(h('p', { class: 'status-line', role: 'status' }, `Not available: ${status.detail}.`),
      h('p', { class: 'hint' }, 'Everything else in the Builder works the same without it. See docs/studio/AI_ASSIST.md to enable a local model.'));
    return box;
  }
  const text = h('textarea', { id: 'assist-text', rows: 4, maxlength: status.max_text });
  const out = h('p', { class: 'status-line', role: 'status', 'aria-live': 'polite' });
  const go = h('button', { type: 'button', onclick: async () => {
    go.disabled = true; go.setAttribute('aria-busy', 'true'); out.className = 'status-line'; out.textContent = 'Asking the local model…';
    try {
      const draft = await api('POST', '/api/studio/assist/draft', { body: { text: text.value } });
      out.className = 'status-line ok'; out.textContent = 'Draft loaded into the form below. It is AI-PROPOSED and nothing is saved.';
      onDraft(draft);
    } catch (e) {
      out.className = 'status-line error';
      out.textContent = errorText(e) + (e instanceof ApiError && e.payload && e.payload.errors ? ' ' + JSON.stringify(e.payload.errors) : '');
      if (!(e instanceof ApiError)) throw e;
    } finally { go.disabled = false; go.removeAttribute('aria-busy'); }
  } }, 'Draft with AI');
  box.append(labelled('Describe the harness', text, `Runs on ${status.detail}. Only this text and the capability list are sent; never files, environment or tokens. The draft is clamped to the Builder defaults.`), go, out);
  return box;
}
